import { z } from 'zod';

// ── 1. Input validation with Zod (allow-list approach) ─────────
const CreateUserSchema = z.object({
  email:   z.string().email().max(255).toLowerCase().trim(),
  name:    z.string().min(1).max(100).regex(/^[\w\s'\-]+$/, 'Invalid characters'),
  age:     z.number().int().min(13).max(120),
  role:    z.enum(['viewer', 'editor', 'admin']).default('viewer'), // allow-list of roles
  website: z.string().url().optional(),
});

// safeParse returns a discriminated union — no try/catch needed
function validateCreateUser(raw) {
  const result = CreateUserSchema.safeParse(raw);
  if (!result.success) {
    // Structured validation errors — never expose internal details
    return { ok: false, errors: result.error.flatten().fieldErrors };
  }
  return { ok: true, data: result.data };
}

console.log(validateCreateUser({ email: ' ALICE@EXAMPLE.COM ', name: 'Alice', age: 25, role: 'admin' }));
// => { ok: true, data: { email: 'alice@example.com', name: 'Alice', age: 25, role: 'admin' } }

console.log(validateCreateUser({ email: 'not-an-email', age: 'old' }));
// => { ok: false, errors: { email: ['Invalid email'], age: [...], name: [...] } }

// ── 2. Fail-fast secrets loading at startup ────────────────────
function loadConfig() {
  const required = ['DATABASE_URL', 'JWT_SECRET', 'REDIS_URL'];
  const missing = required.filter(k => !process.env[k]);
  if (missing.length > 0) {
    // Crash immediately with a clear error, not mid-request with a cryptic one
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
  return {
    db:    process.env.DATABASE_URL,  // Never hardcoded
    jwt:   process.env.JWT_SECRET,    // Rotatable without code changes
    redis: process.env.REDIS_URL,
  };
}

// ── 3. Defense in depth: rate limiting as one of many layers ──
function createRateLimiter(windowMs, maxRequests) {
  const counts = new Map();
  return (req, res, next) => {
    const key = req.ip;
    const now = Date.now();
    const entry = counts.get(key) || { count: 0, resetAt: now + windowMs };
    if (now > entry.resetAt) { entry.count = 0; entry.resetAt = now + windowMs; }
    entry.count++;
    counts.set(key, entry);
    if (entry.count > maxRequests) {
      return res.status(429).json({ error: 'Too many requests' });
    }
    next();
  };
}
// This sits alongside input validation, authentication, and authorization —
// not instead of them. That is what defense in depth means.
