// ── Secrets management tiers ─────────────────────────────────
//
// Tier │ Storage                      │ Who can read         │ Use for
// ─────┼──────────────────────────────┼──────────────────────┼───────────────────────
// 1    │ Hardcoded in source code     │ Anyone with repo     │ NEVER
// 2    │ .env committed to git        │ Anyone with repo     │ NEVER
// 3    │ .env gitignored              │ Local machine only   │ Local dev only
// 4    │ CI/CD secrets (GitHub/GitLab)│ CI runners only      │ Build & deploy secrets
// 5    │ Cloud secrets manager        │ IAM-controlled, audited │ Production secrets
// 6    │ HSM / hardware vault         │ Hardware-enforced    │ PKI keys, payment HSM

// ── .gitignore essentials ────────────────────────────────────
const GITIGNORE_MUST_HAVE = [
  '.env',
  '.env.*',
  '!.env.example',      // DO commit the example template (no real values)
  '*.pem',
  '*.key',
  '*.p12',
  '*.pfx',
  'secrets.json',
  'credentials.json',
  'service-account*.json',
  '**/*.env',
];

// ── HTTP security headers every response should include ───────
const SECURITY_HEADERS = {
  'Strict-Transport-Security': 'max-age=63072000; includeSubDomains; preload',
  'X-Content-Type-Options':    'nosniff',
  'X-Frame-Options':           'DENY',
  'Referrer-Policy':           'strict-origin-when-cross-origin',
  'Permissions-Policy':        'geolocation=(), microphone=(), camera=()',
  'Content-Security-Policy':   "default-src 'self'; script-src 'self'; object-src 'none'",
};

// ── PostgreSQL: minimal app user permissions ─────────────────
