// ── Dependency audit — CI gate ────────────────────────────────
// In package.json:
// {
//   "scripts": {
//     "audit:ci": "npm audit --audit-level=high"
//     // Fails the build if any HIGH or CRITICAL CVE found
//     // Run alongside your test suite in every PR
//   }
// }
//
// For stricter supply-chain analysis:
// npx socket check  (Socket.dev — flags behavior changes, new maintainers, postinstall scripts)
// npx snyk test --severity-threshold=high

// ── Defense in depth: headers middleware (Express example) ────
function securityHeaders(req, res, next) {
  Object.entries(SECURITY_HEADERS).forEach(([header, value]) => {
    res.setHeader(header, value);
  });
  next();
}
