// ── Rotate JWT secrets with a key set ────────────────────────
// Instead of a single JWT_SECRET, maintain a key set:
// CURRENT_JWT_SECRET  — signs new tokens
// PREVIOUS_JWT_SECRET — still valid for tokens issued before rotation
// When rotating: PREVIOUS = CURRENT, generate new CURRENT
// Tokens issued before rotation remain valid through their expiry period
function verifyTokenWithKeyRotation(token, currentSecret, previousSecret) {
  try {
    // Try current key first (fast path)
    return { valid: true, payload: verifyJwt(token, currentSecret) };
  } catch {
    try {
      // Fall back to previous key for in-flight tokens
      return { valid: true, payload: verifyJwt(token, previousSecret) };
    } catch {
      return { valid: false, payload: null };
    }
  }
}
function verifyJwt(token, secret) {
  // In real code: return jwt.verify(token, secret);
  if (!token || !secret) throw new Error('Invalid');
  return { sub: 'user-id', exp: Date.now() / 1000 + 900 };
}
